import random
import string
from typing import List

# This generator produces valid libconfig configuration documents as bytes.
# It aims to cover groups, arrays, lists, scalar types, formatting options,
# numeric formats (hex/oct/bin), includes, comments, and various edge cases.

_SCALAR_NAMES = [
    "enabled", "count", "ratio", "title", "path", "flag", "threshold",
    "timeout", "mode", "version", "pi", "answer", "mask", "bits",
]

_GROUP_NAMES = [
    "root", "settings", "network", "database", "server", "client",
    "logging", "features", "limits", "ui", "cache", "tls", "http",
]

_LIST_NAMES = [
    "items", "values", "names", "hosts", "ports", "paths", "flags",
    "ratios", "points", "masks",
]

_STRING_SAMPLES = [
    "hello", "world", "libconfig", "test", "abc123", "with spaces",
    "unicode — ok?", "escape\\sequence", "quote\"inside\"", "tab\tchar",
    "line\\nbreak", "path/like/value", "C:/windows/path", "~/home",
]

# Numeric samples in various formats accepted by libconfig
_INT_SAMPLES = [0, 1, -1, 2, -2, 7, 8, 9, 10, 15, 16, 31, 32, 63, 64, 127,
                128, 255, 256, 511, 512, 1023, 1024, 2048, 4096, 65535,
                -2147483648, 2147483647]
_LL_SAMPLES = [0, 1, -1, 42, -42, 2**40, -(2**40), 2**63-1, -(2**63)+1]
_FLOAT_SAMPLES = [0.0, -0.0, 1.0, -1.0, 3.1415926535, 2.718281828, 1e-6,
                  1e6, -1e6, 6.022e23, -9.109e-31, 0.3333333333]

_BOOL_LIT = ["true", "false"]

def _rand_choice(rnd: random.Random, arr: List):
    return arr[rnd.randrange(len(arr))]

def _ident(rnd: random.Random, base_list: List[str]) -> str:
    base = _rand_choice(rnd, base_list)
    suffix = ""
    if rnd.random() < 0.7:
        # add alnum/underscore suffix to broaden variety
        n = rnd.randint(0, 4)
        for _ in range(n):
            suffix += rnd.choice(string.ascii_lowercase + string.digits + "_")
    return base + suffix

def _string_literal(rnd: random.Random) -> str:
    if rnd.random() < 0.6:
        s = _rand_choice(rnd, _STRING_SAMPLES)
    else:
        # generate random string with escapes
        length = rnd.randint(0, 20)
        chars = []
        for _ in range(length):
            ch = rnd.choice(string.printable)
            if ch == '"':
                chars.append('\\"')
            elif ch == '\\':
                chars.append('\\\\')
            elif ch == '\n':
                chars.append('\\n')
            elif ch == '\t':
                chars.append('\\t')
            else:
                # avoid control chars outside printable
                if ch in "\r\x0b\x0c":
                    chars.append(' ')
                else:
                    chars.append(ch)
        s = ''.join(chars)
    return '"' + s + '"'

def _int_literal(rnd: random.Random) -> str:
    style = rnd.random()
    if style < 0.5:
        return str(_rand_choice(rnd, _INT_SAMPLES))
    elif style < 0.75:
        # hexadecimal
        v = abs(_rand_choice(rnd, _INT_SAMPLES))
        return "0x" + format(v, "x")
    elif style < 0.9:
        # octal (use 0 prefix, avoid leading zeros confusion for 0 itself)
        v = abs(_rand_choice(rnd, _INT_SAMPLES))
        return "0" + format(v, "o")
    else:
        # binary (0b...)
        v = abs(_rand_choice(rnd, _INT_SAMPLES))
        return "0b" + format(v, "b")

def _ll_literal(rnd: random.Random) -> str:
    v = _rand_choice(rnd, _LL_SAMPLES)
    return str(v)

def _float_literal(rnd: random.Random) -> str:
    v = _rand_choice(rnd, _FLOAT_SAMPLES)
    fmt = rnd.random()
    if fmt < 0.5:
        return ("%.*f" % (rnd.randint(0, 10), v)).rstrip('0').rstrip('.') if rnd.random() < 0.8 else str(v)
    else:
        # scientific
        return ("%.*e" % (rnd.randint(0, 8), v))

def _bool_literal(rnd: random.Random) -> str:
    return _rand_choice(rnd, _BOOL_LIT)

def _scalar_assignment(rnd: random.Random) -> str:
    name = _ident(rnd, _SCALAR_NAMES)
    t = rnd.random()
    if t < 0.25:
        val = _int_literal(rnd)
    elif t < 0.45:
        val = _ll_literal(rnd)
    elif t < 0.7:
        val = _float_literal(rnd)
    elif t < 0.85:
        val = _bool_literal(rnd)
    else:
        val = _string_literal(rnd)
    sep = ";" if rnd.random() < 0.7 else (":" if rnd.random() < 0.5 else ";")
    # support option for colon assignment for groups/non-groups; here on scalars keep '='
    assign_op = "=" if rnd.random() < 0.9 else ":"
    return f"{name} {assign_op} {val}{sep}\n"

def _array_of(rnd: random.Random, kind: str, minlen=0, maxlen=8) -> str:
    n = rnd.randint(minlen, maxlen)
    elems = []
    for _ in range(n):
        if kind == "int":
            elems.append(_int_literal(rnd))
        elif kind == "int64":
            elems.append(_ll_literal(rnd))
        elif kind == "float":
            elems.append(_float_literal(rnd))
        elif kind == "bool":
            elems.append(_bool_literal(rnd))
        elif kind == "string":
            elems.append(_string_literal(rnd))
        else:
            elems.append("0")
    return "[ " + ", ".join(elems) + " ]" + (";\n" if rnd.random() < 0.9 else "\n")

def _list_mixed(rnd: random.Random, minlen=0, maxlen=8) -> str:
    n = rnd.randint(minlen, maxlen)
    elems = []
    for _ in range(n):
        t = rnd.random()
        if t < 0.2:
            elems.append(_int_literal(rnd))
        elif t < 0.35:
            elems.append(_float_literal(rnd))
        elif t < 0.55:
            elems.append(_bool_literal(rnd))
        elif t < 0.75:
            elems.append(_string_literal(rnd))
        else:
            # small inline group or array to mix aggregates
            if rnd.random() < 0.5:
                elems.append(_array_of(rnd, _rand_choice(rnd, ["int", "float", "bool"]), 0, 4).strip().rstrip(';'))
            else:
                elems.append("{ name = " + _string_literal(rnd) + "; }")
    return "( " + ", ".join(elems) + " )" + (";\n" if rnd.random() < 0.9 else "\n")

def _comment_block(rnd: random.Random) -> str:
    if rnd.random() < 0.5:
        return "// " + _rand_choice(rnd, _STRING_SAMPLES) + "\n"
    else:
        text = _rand_choice(rnd, _STRING_SAMPLES)
        return "/* " + text + " */\n"

def _include_line(rnd: random.Random) -> str:
    # Reference a plausible filename; fuzzer harness will attach random file content.
    # Using relative and absolute-like paths to exercise include resolution.
    candidates = [
        "\"included.cfg\"", "\"conf.d/common.cfg\"", "\"/etc/libconfig/sample.cfg\"",
        "\"../up.cfg\"", "\"./nested/in.cfg\""
    ]
    return "@include " + _rand_choice(rnd, candidates) + ";\n"

def _group_block(rnd: random.Random, depth: int) -> str:
    name = _ident(rnd, _GROUP_NAMES)
    use_colon = rnd.random() < 0.2
    header = f"{name} {'=' if not use_colon else ':'} {{\n"
    body = ""
    # insert a comment or include occasionally
    if rnd.random() < 0.4:
        body += _comment_block(rnd)
    if rnd.random() < 0.3:
        body += _include_line(rnd)

    # add some scalar assignments
    for _ in range(rnd.randint(0, 4)):
        body += _scalar_assignment(rnd)

    # add arrays/lists
    for _ in range(rnd.randint(0, 3)):
        aname = _ident(rnd, _LIST_NAMES)
        kind = _rand_choice(rnd, ["int", "int64", "float", "bool", "string"])
        body += f"{aname} = " + _array_of(rnd, kind, 0, rnd.randint(2, 8))

    for _ in range(rnd.randint(0, 2)):
        lname = _ident(rnd, _LIST_NAMES)
        body += f"{lname} = " + _list_mixed(rnd, 0, rnd.randint(2, 6))

    # nested groups (limit depth)
    if depth < 2:
        for _ in range(rnd.randint(0, 2)):
            body += _group_block(rnd, depth + 1)

    footer = "}" + (";\n" if rnd.random() < 0.9 else "\n")
    return header + body + footer

def _root_document(rnd: random.Random) -> str:
    parts = []
    # global comments and options
    if rnd.random() < 0.6:
        parts.append(_comment_block(rnd))
    if rnd.random() < 0.3:
        parts.append(_include_line(rnd))

    # some top-level scalars
    for _ in range(rnd.randint(0, 4)):
        parts.append(_scalar_assignment(rnd))

    # top-level arrays/lists
    for _ in range(rnd.randint(0, 3)):
        name = _ident(rnd, _LIST_NAMES)
        kind = _rand_choice(rnd, ["int", "int64", "float", "bool", "string"])
        parts.append(f"{name} = " + _array_of(rnd, kind, 0, rnd.randint(2, 10)))

    if rnd.random() < 0.5:
        name = _ident(rnd, _LIST_NAMES)
        parts.append(f"{name} = " + _list_mixed(rnd, 0, rnd.randint(2, 8)))

    # a few groups
    groups = rnd.randint(1, 3)
    for _ in range(groups):
        parts.append(_group_block(rnd, 0))

    # trailing comment
    if rnd.random() < 0.5:
        parts.append(_comment_block(rnd))

    return ''.join(parts)


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)

    # Choose one of several document profiles to diversify structure.
    profile = rnd.random()
    doc = ""
    if profile < 0.25:
        # Minimal but valid: one scalar and one group
        name = _ident(rnd, _SCALAR_NAMES)
        doc += f"{name} = {_bool_literal(rnd)};\n"
        doc += _group_block(rnd, 0)
    elif profile < 0.5:
        # Array-centric
        name = _ident(rnd, _LIST_NAMES)
        doc += f"// array-centric document\n{name} = " + _array_of(rnd, _rand_choice(rnd, ["int", "float", "bool", "string"]), 1, 12)
        doc += _group_block(rnd, 0)
    elif profile < 0.75:
        # List-heavy with includes
        doc += _include_line(rnd)
        for _ in range(rnd.randint(1, 3)):
            lname = _ident(rnd, _LIST_NAMES)
            doc += f"{lname} = " + _list_mixed(rnd, 1, 8)
        doc += _group_block(rnd, 0)
    else:
        # Rich mixed document
        doc = _root_document(rnd)

    # Ensure size limit
    b = doc.encode('utf-8', errors='ignore')
    if len(b) > 4096:
        # Trim at statement boundary if possible
        cut = b[:4096]
        # try to cut back to last semicolon or closing brace to keep validity
        for marker in [b';', b'}', b'\n']:
            idx = cut.rfind(marker)
            if idx != -1 and idx > 0:
                cut = cut[:idx+1]
                break
        b = cut
    return b

import random
import string
from typing import List

# Generator for libconfig configuration text
# Aim: produce syntactically valid and interesting libconfig documents that
# exercise scalars, arrays, lists, groups, nesting, formatting options
# (hex/bin/oct), booleans, strings (with escapes), numbers (int, int64-ish
# ranges, floats, scientific), include directives, and comments.
# The output is a NUL-terminated C-string buffer (as bytes) suitable for
# config_read_string / Config::readString.

BOOLS = ["true", "false"]
FMT_NUMS = [
    # decimal ints
    lambda r: str(r.randint(-2147483648, 2147483647)),
    # 64-bitish
    lambda r: str(r.randint(-2**63 + 1, 2**63 - 1)),
    # hex (with 0x)
    lambda r: "0x" + ("" if r.random() < 0.5 else "-") + format(r.getrandbits(32), "x"),
    # octal (0 prefix)
    lambda r: "0" + format(r.randint(0, 2**16), "o"),
    # binary (0b)
    lambda r: "0b" + "".join(r.choice("01") for _ in range(r.randint(1, 32))),
    # float
    lambda r: ("-" if r.random() < 0.5 else "") + str(r.uniform(1e-6, 1e6)),
    # scientific
    lambda r: f"{r.uniform(-1e6,1e6):.8e}",
]

ESCAPES = ["\\n", "\\t", "\\r", "\\\"", "\\\\"]

KEY_CHARS = string.ascii_letters + string.digits + "_"


def rand_identifier(r: random.Random, min_len=1, max_len=12) -> str:
    l = r.randint(min_len, max_len)
    first = r.choice(string.ascii_letters + "_")
    rest = "".join(r.choice(KEY_CHARS) for _ in range(l - 1))
    return first + rest


def rand_string(r: random.Random) -> str:
    # mixture of simple, escaped, and multi-line-like content
    length = r.randint(0, 40)
    chars = []
    for _ in range(length):
        if r.random() < 0.15:
            chars.append(r.choice(ESCAPES))
        else:
            ch = r.choice(string.printable)
            # avoid raw quotes and backslashes unless escaped
            if ch in ['"', "\\"]:
                chars.append("\\" + ch)
            else:
                # filter non-newline control chars
                if ch in "\x0b\x0c\x0b\x0c":
                    ch = " "
                chars.append(ch)
    return '"' + "".join(chars) + '"'


def rand_value(r: random.Random) -> str:
    kind = r.random()
    if kind < 0.18:
        return r.choice(BOOLS)
    elif kind < 0.55:
        return r.choice(FMT_NUMS)(r)
    elif kind < 0.78:
        return rand_string(r)
    else:
        # array or list
        if r.random() < 0.5:
            # array: homogeneous typed values enclosed in [ ]
            # libconfig arrays are typed; we choose a type and keep values consistent
            tsel = r.random()
            if tsel < 0.33:
                vals = [r.choice(FMT_NUMS)(r) for _ in range(r.randint(0, 6))]
            elif tsel < 0.66:
                vals = [r.choice(BOOLS) for _ in range(r.randint(0, 6))]
            else:
                vals = [rand_string(r) for _ in range(r.randint(0, 6))]
            return "[ " + ", ".join(vals) + " ]"
        else:
            # list: heterogeneous allowed, use ( ... ) in libconfig
            items = []
            for _ in range(r.randint(0, 6)):
                items.append(rand_value(r if r.random() < 0.8 else random.Random(r.randint(0, 1<<30))))
            return "( " + ", ".join(items) + " )"


def rand_assignment(r: random.Random) -> str:
    name = rand_identifier(r)
    val = rand_value(r)
    # Optionally annotate numeric with format override using hex/bin/oct keywords is not libconfig syntax;
    # instead, numbers themselves carry base (0x, 0, 0b). We occasionally add comments.
    stmt = f"{name} = {val};"
    if r.random() < 0.3:
        stmt += f" // {rand_identifier(r)}\n"
    else:
        stmt += "\n"
    return stmt


def rand_group(r: random.Random, depth: int) -> str:
    name = rand_identifier(r)
    body = []
    # Optionally specify format of some children via hex/bin/oct using per-setting format suffix is C API; in text it's not explicit.
    # We'll just produce valid members.
    count = r.randint(0, 6)
    for _ in range(count):
        if depth < 3 and r.random() < 0.45:
            body.append(rand_group(r, depth + 1))
        else:
            body.append(rand_assignment(r))
    inner = "".join(body)
    sep = ":" if r.random() < 0.5 else "="  # libconfig allows group: { ... } or group = { ... }
    return f"{name} {sep} {{\n{inner}}};\n"


def rand_root_items(r: random.Random) -> List[str]:
    items: List[str] = []
    # Top-level comments and optional include statements.
    if r.random() < 0.5:
        items.append("// top-level comment\n")
    # Some include syntaxes accepted by libconfig: include("file"); or @include "file"
    # We'll emit include statements using a plausible syntax; parsers often support both.
    if r.random() < 0.6:
        inc_style = r.random()
        fname = rand_identifier(r, 3, 10) + ".cfg"
        if inc_style < 0.5:
            items.append(f'@include "{fname}"\n')
        else:
            items.append(f'include("{fname}");\n')
    # A mixture of assignments and groups
    n = r.randint(3, 10)
    for _ in range(n):
        choice = r.random()
        if choice < 0.4:
            items.append(rand_assignment(r))
        elif choice < 0.75:
            items.append(rand_group(r, 0))
        else:
            # unnamed list or array assigned to an identifier at top-level as well
            items.append(rand_assignment(r))
    return items


def make_document(r: random.Random) -> str:
    doc = ""
    # Optionally set default formatting hints via comments (libconfig options are code-level, not syntax).
    if r.random() < 0.5:
        doc += "/* Generated config */\n"
    # Optionally define a root group explicitly
    if r.random() < 0.4:
        # root group contents
        inner = "".join(rand_root_items(r))
        doc += "root: {\n" + inner + "};\n"
    else:
        doc += "".join(rand_root_items(r))
    # Add trailing whitespace/newlines
    if r.random() < 0.7:
        doc += "\n"
    return doc


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Create multiple variants and pick one with bounded size
    for _ in range(10):
        text = make_document(r)
        if len(text.encode('utf-8')) <= 4000:
            # Ensure NUL-terminated buffer for C API
            return text.encode('utf-8') + b"\x00"
    # Fallback: simple minimal valid assignment
    minimal = "foo = 1;\n"
    return minimal.encode('utf-8') + b"\x00"

import random
import string
from typing import List

# This generator produces valid libconfig configuration text snippets focusing on string settings,
# as exercised by the provided fuzz stubs. The stubs call config_read_string/readString with
# a document that defines string settings, then pass our FUZZ_PARAM_STR() value as the new
# string value. Therefore, our output should be a plausible arbitrary string (no embedded NUL),
# and varied to exercise different internal behaviors (ASCII, Unicode-like UTF-8, escapes,
# long/short, edge characters), while remaining valid as a plain string payload.
#
# The returned bytes are intended to be consumed by FUZZ_PARAM_STR() and similar. We ensure
# the data is NUL-free and <= 4096 bytes.

MAX_LEN = 1024  # keep reasonably small; stubs may further truncate


def _rand_ascii(rng: random.Random, min_len: int, max_len: int) -> str:
    length = rng.randint(min_len, max_len)
    # Include common visible ASCII plus whitespace that might be interesting in strings
    alphabet = string.ascii_letters + string.digits + string.punctuation + " \t"
    # Avoid embedded NULs and prefer balanced quotes/backslashes to stress escaping usage in downstream
    s = ''.join(rng.choice(alphabet) for _ in range(length))
    return s


def _rand_utf8(rng: random.Random, min_len: int, max_len: int) -> str:
    length = rng.randint(min_len, max_len)
    # Mix ASCII with some multi-byte UTF-8 code points
    # Selected ranges: Latin-1 Supplement, Greek, Cyrillic, Emoji subset
    def rand_cp():
        choice = rng.random()
        if choice < 0.5:
            return rng.randint(0x20, 0x7E)
        elif choice < 0.7:
            return rng.randint(0xA1, 0xFF)
        elif choice < 0.85:
            return rng.randint(0x0370, 0x03FF)
        elif choice < 0.95:
            return rng.randint(0x0400, 0x04FF)
        else:
            # a small emoji range
            return rng.randint(0x1F600, 0x1F64F)
    chars: List[str] = []
    while len(chars) < length:
        cp = rand_cp()
        try:
            chars.append(chr(cp))
        except ValueError:
            continue
    return ''.join(chars)


def _escaped_components(rng: random.Random) -> str:
    # Create a string with many C/JSON-like escapes that may appear in libconfig strings
    escapes = [
        "\\n", "\\r", "\\t", "\\b", "\\f", "\\\\", "\\\"",
        # octal and hex-style sequences often parsed by C-like parsers
        "\\x00", "\\x1F", "\\x7F",
        "\\101", "\\377",
    ]
    words = [
        "alpha", "beta", "gamma", "delta", "path", "C:\\\\Temp\\\\file.txt",
        "key=value", "a:b;c", "{braces}", "[array]", "(paren)", "<xml>",
    ]
    parts = []
    for _ in range(rng.randint(3, 10)):
        if rng.random() < 0.5:
            parts.append(rng.choice(words))
        else:
            parts.append(rng.choice(escapes))
    return ''.join(parts)


def _numeric_like(rng: random.Random) -> str:
    # Strings that look like numbers in various bases; useful because libconfig has numeric formats
    variants = []
    # decimal, signed, large
    variants.append(str(rng.randint(-2**31, 2**31 - 1)))
    # 64-bit range edge-like
    variants.append(str(rng.randint(-2**63 + 1, 2**63 - 2)))
    # hex-like
    variants.append("0x" + ''.join(rng.choice('0123456789abcdef') for _ in range(rng.randint(1, 16))))
    # octal-like
    variants.append("0" + ''.join(rng.choice('01234567') for _ in range(rng.randint(1, 16))))
    # binary-like
    variants.append("0b" + ''.join(rng.choice('01') for _ in range(rng.randint(1, 32))))
    # float-like
    variants.append(f"{rng.uniform(-1e9, 1e9):.6f}")
    # scientific
    variants.append(f"{rng.uniform(-1e5, 1e5)}e{rng.randint(-12, 12)}")
    return rng.choice(variants)


def _bool_like(rng: random.Random) -> str:
    return rng.choice(["true", "false", "on", "off", "yes", "no", "True", "False"])


def _path_like(rng: random.Random) -> str:
    # Mix POSIX and Windows style
    posix_parts = ["usr", "local", "bin", "lib", "etc", "var", "tmp", "home", "user", "config"]
    win_parts = ["C:", "D:", "Users", "AppData", "Local", "Temp", "Program Files", "libconfig"]
    if rng.random() < 0.5:
        depth = rng.randint(1, 6)
        return "/" + "/".join(rng.choice(posix_parts) for _ in range(depth))
    else:
        depth = rng.randint(2, 6)
        return "\\".join(rng.choice(win_parts) for _ in range(depth))


def _quote_balance(rng: random.Random) -> str:
    # Build strings containing quotes/backslashes that are still valid as raw string payloads
    segments = [
        "quote\"inside", "backslash\\trail", "mix\\\"both\"", "semi;colon", "colon:here",
        "comma,sep", "spaces  inside", "tabs\there", "braces{}", "brackets[]",
    ]
    # Assemble with safe separators
    out = []
    for _ in range(rng.randint(2, 6)):
        out.append(rng.choice(segments))
    return ' '.join(out)


def _truncate_bytes(b: bytes, limit: int) -> bytes:
    if len(b) <= limit:
        return b
    return b[:limit]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a theme to generate diverse yet valid strings.
    theme = rng.choice([
        "ascii", "utf8", "escaped", "numeric", "bool", "path", "quotes", "mixed"
    ])

    if theme == "ascii":
        s = _rand_ascii(rng, 0, min(256, MAX_LEN))
    elif theme == "utf8":
        s = _rand_utf8(rng, 1, min(128, MAX_LEN // 4))
    elif theme == "escaped":
        s = _escaped_components(rng)
    elif theme == "numeric":
        s = _numeric_like(rng)
    elif theme == "bool":
        s = _bool_like(rng)
    elif theme == "path":
        s = _path_like(rng)
    elif theme == "quotes":
        s = _quote_balance(rng)
    else:  # mixed
        parts = [
            _rand_ascii(rng, 1, 20),
            _escaped_components(rng),
            _rand_utf8(rng, 1, 10),
            _numeric_like(rng),
            _bool_like(rng),
            _path_like(rng),
        ]
        rng.shuffle(parts)
        s = ' '.join(parts)

    # Ensure there is no embedded NUL and limit total size.
    s = s.replace('\x00', '')
    b = s.encode('utf-8', errors='ignore')
    b = _truncate_bytes(b, min(MAX_LEN, 4096))
    # Guarantee no NUL bytes in final output and ensure NUL-terminated semantics when consumed as C string.
    b = b.replace(b"\x00", b"")

    return b
